/**
 * LuxeShop - Ecommerce Home Page
 * Vanilla JavaScript Functionality
 */

// Initialize all functionality when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    initNavigation();
    initCountdown();
    initNewsletter();
    initProductInteractions();
});

/**
 * Navigation Toggle
 */
function initNavigation() {
    const navToggle = document.querySelector('.nav-toggle');
    const navMenu = document.querySelector('.nav-menu');

    if (!navToggle || !navMenu) return;

    // Toggle menu on button click
    navToggle.addEventListener('click', () => {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        navToggle.setAttribute('aria-expanded', !isExpanded);
        navMenu.classList.toggle('active');
    });

    // Close menu when a link is clicked
    const navLinks = navMenu.querySelectorAll('.nav-link');
    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            navToggle.setAttribute('aria-expanded', 'false');
            navMenu.classList.remove('active');
        });
    });

    // Close menu when clicking outside
    document.addEventListener('click', (e) => {
        if (!e.target.closest('.nav') && !e.target.closest('.nav-toggle')) {
            navToggle.setAttribute('aria-expanded', 'false');
            navMenu.classList.remove('active');
        }
    });
}

/**
 * Countdown Timer
 */
function initCountdown() {
    const updateCountdown = () => {
        // Set end time to 2 days from now
        const now = new Date();
        const endTime = new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000);

        const updateDisplay = () => {
            const currentTime = new Date();
            const difference = endTime - currentTime;

            if (difference <= 0) {
                document.getElementById('days').textContent = '00';
                document.getElementById('hours').textContent = '00';
                document.getElementById('minutes').textContent = '00';
                document.getElementById('seconds').textContent = '00';
                return;
            }

            const days = Math.floor(difference / (1000 * 60 * 60 * 24));
            const hours = Math.floor((difference % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((difference % (1000 * 60)) / 1000);

            document.getElementById('days').textContent = String(days).padStart(2, '0');
            document.getElementById('hours').textContent = String(hours).padStart(2, '0');
            document.getElementById('minutes').textContent = String(minutes).padStart(2, '0');
            document.getElementById('seconds').textContent = String(seconds).padStart(2, '0');
        };

        // Update immediately and then every second
        updateDisplay();
        setInterval(updateDisplay, 1000);
    };

    updateCountdown();
}

/**
 * Newsletter Form Validation
 */
function initNewsletter() {
    const form = document.querySelector('.newsletter-form');
    const emailInput = form?.querySelector('input[type="email"]');
    const errorMessage = document.getElementById('email-error');

    if (!form || !emailInput) return;

    const validateEmail = (email) => {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    };

    const showError = (message) => {
        errorMessage.textContent = message;
        emailInput.setAttribute('aria-invalid', 'true');
    };

    const clearError = () => {
        errorMessage.textContent = '';
        emailInput.setAttribute('aria-invalid', 'false');
    };

    // Real-time validation
    emailInput.addEventListener('input', () => {
        if (emailInput.value.trim() === '') {
            clearError();
        } else if (!validateEmail(emailInput.value)) {
            showError('Please enter a valid email address');
        } else {
            clearError();
        }
    });

    // Form submission
    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const email = emailInput.value.trim();

        if (!email) {
            showError('Please enter your email address');
            emailInput.focus();
            return;
        }

        if (!validateEmail(email)) {
            showError('Please enter a valid email address');
            emailInput.focus();
            return;
        }

        // Simulate subscription
        const button = form.querySelector('.btn');
        const originalText = button.textContent;
        button.textContent = 'Subscribed! ✓';
        button.disabled = true;

        clearError();
        emailInput.value = '';

        // Reset after 3 seconds
        setTimeout(() => {
            button.textContent = originalText;
            button.disabled = false;
        }, 3000);
    });
}

/**
 * Product Interactions
 */
function initProductInteractions() {
    const addToCartButtons = document.querySelectorAll('.product-card .btn-secondary');

    addToCartButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            e.preventDefault();

            const card = button.closest('.product-card');
            const productName = card.querySelector('h3 a').textContent;
            const originalText = button.textContent;

            // Visual feedback
            button.textContent = 'Added! ✓';
            button.style.backgroundColor = 'var(--color-bg-tertiary)';
            button.style.borderColor = 'var(--color-success)';
            button.style.color = 'var(--color-success)';

            // Log to console (simulating cart addition)
            console.log(`Added to cart: ${productName}`);

            // Reset after 2 seconds
            setTimeout(() => {
                button.textContent = originalText;
                button.style.backgroundColor = '';
                button.style.borderColor = '';
                button.style.color = '';
            }, 2000);
        });
    });
}

/**
 * Smooth scroll for internal links
 */
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href === '#' || href === '') return;

        e.preventDefault();
        const target = document.querySelector(href);
        if (target) {
            target.scrollIntoView({ behavior: 'smooth' });
        }
    });
});

/**
 * Add keyboard support for icon buttons
 */
document.querySelectorAll('.icon-btn').forEach(button => {
    button.addEventListener('keypress', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            button.click();
        }
    });
});

