}

.btn-outline {
    background-color: transparent;
    color: var(--color-accent);
    border: 2px solid var(--color-accent);
}

.btn-outline:hover,
.btn-outline:active {
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
}

/* ===========================
   Layout
   =========================== */

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

.section {
    padding: var(--spacing-2xl) 0;
}

.section > .container > h2 {
    text-align: center;
}

/* ===========================
   Header & Navigation
   =========================== */

.header {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo h1 {
    font-size: var(--font-size-2xl);
    margin: 0;
    letter-spacing: 1px;
    color: var(--color-accent);
}

.nav {
    flex: 1;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    color: var(--color-text-primary);
    cursor: pointer;
    width: 32px;
    height: 32px;
    flex-direction: column;
    justify-content: center;
    gap: 6px;
}

.nav-toggle span {
    display: block;
    width: 100%;
    height: 2px;
    background-color: var(--color-text-primary);
    transition: all var(--transition-base);
    border-radius: 1px;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
    transform: translateY(8px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
    opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:nth-child(3) {
    transform: translateY(-8px) rotate(-45deg);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-xl);
}

.nav-link {
    color: var(--color-text-secondary);
    font-weight: var(--font-weight-medium);
    position: relative;
    padding-bottom: 4px;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-link:hover {
    color: var(--color-accent);
}

.nav-link:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
}

.icon-btn {
    background: none;
    border: none;
    color: var(--color-text-primary);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    transition: color var(--transition-fast);
    border-radius: var(--radius-sm);
}

.icon-btn:hover {
    color: var(--color-accent);
    background-color: rgba(212, 175, 55, 0.1);
}

/* ===========================
   Hero Section
   =========================== */

.hero {
    background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%);
    padding: var(--spacing-2xl) var(--spacing-lg);
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: 
        radial-gradient(circle at 20% 50%, rgba(212, 175, 55, 0.15) 0%, transparent 50%),
        radial-gradient(circle at 80% 80%, rgba(212, 175, 55, 0.1) 0%, transparent 50%);
    pointer-events: none;
}

.hero-content {
    position: relative;
    z-index: 1;
    max-width: 600px;
}

.hero-content h2 {
    font-size: var(--font-size-4xl);
    margin-bottom: var(--spacing-md);
    color: var(--color-accent);
}

.hero-content p {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-xl);
    color: var(--color-text-secondary);
}

/* ===========================
   Products Section
   =========================== */

.featured-products {
    background-color: var(--color-bg-primary);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--color-accent);
    box-shadow: var(--shadow-md);
    transform: translateY(-4px);
}

.product-image {
    position: relative;
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
    aspect-ratio: 1;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-sm);
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-bold);
    z-index: 1;
}

.product-info {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-info h3 {
    margin-bottom: var(--spacing-sm);
    font-size: var(--font-size-lg);
}

.product-info h3 a {
    color: var(--color-text-primary);
}

.product-info h3 a:hover {
    color: var(--color-accent);
}

.product-category {
    font-size: var(--font-size-sm);
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-sm);
}

.rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-sm);
}

.stars {
    color: var(--color-accent);
    letter-spacing: 2px;
}

.reviews {
    color: var(--color-text-muted);
}

.product-price {
    margin-bottom: var(--spacing-md);
}

.price {
    font-size: var(--font-size-lg);
    font-weight: var(--font-weight-bold);
    color: var(--color-accent);
}

.original-price {
    text-decoration: line-through;
    color: var(--color-text-muted);
    margin-right: var(--spacing-sm);
    font-size: var(--font-size-sm);
}

.product-card .btn {
    width: 100%;
    margin-top: auto;
}

/* ===========================
   Deals Section
   =========================== */

.deals {
    background: linear-gradient(180deg, var(--color-bg-secondary) 0%, var(--color-bg-primary) 100%);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.deal-card {
    background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    transition: all var(--transition-base);
}

.deal-card:hover {
    border-color: var(--color-accent);
    box-shadow: var(--shadow-md);
    transform: translateY(-4px);
}

.deal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--spacing-md);
}

.deal-header h3 {
    margin: 0;
    color: var(--color-accent);
}

.discount-badge {
    background-color: var(--color-accent);
    color: var(--color-bg-primary);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-sm);
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-bold);
    white-space: nowrap;
}

.deal-description {
    font-size: var(--font-size-base);
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-md);
}

.countdown {
    display: flex;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
    padding: var(--spacing-md);
    background-color: var(--color-bg-tertiary);
    border-radius: var(--radius-md);
}

.time-unit {
    flex: 1;
    text-align: center;
}

.time-value {
    display: block;
    font-size: var(--font-size-2xl);
    font-weight: var(--font-weight-bold);
    color: var(--color-accent);
    margin-bottom: var(--spacing-xs);
}

.time-label {
    display: block;
    font-size: var(--font-size-sm);
    color: var(--color-text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.bundle-items {
    list-style: none;
    margin-bottom: var(--spacing-lg);
}

.bundle-items li {
    padding: var(--spacing-sm) 0;
    color: var(--color-text-secondary);
    font-size: var(--font-size-sm);
}

.deal-card .btn {
    width: 100%;
}

/* ===========================
   Editorial Section
   =========================== */

.editorial {
    background-color: var(--color-bg-primary);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--color-accent);
    box-shadow: var(--shadow-lg);
    transform: translateY(-8px);
}

.editorial-image {
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
    aspect-ratio: 4/2.5;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.editorial-category {
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-bold);
    color: var(--color-accent);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-sm);
}

.editorial-card h3 {
    margin-bottom: var(--spacing-md);
}

.editorial-card h3 a {
    color: var(--color-text-primary);
}

.editorial-card h3 a:hover {
    color: var(--color-accent);
}

.editorial-card p {
    flex: 1;
    margin-bottom: var(--spacing-md);
}

.read-more {
    font-weight: var(--font-weight-semibold);
    display: inline-block;
}

.read-more:hover {
    transform: translateX(4px);
    transition: transform var(--transition-fast);
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter {
    background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
    border-top: 1px solid var(--color-border);
    border-bottom: 1px solid var(--color-border);
}

.newsletter-content {
    text-align: center;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-content h2 {
    color: var(--color-accent);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
    justify-content: center;
}

.form-group {
    flex: 1;
    min-width: 250px;
}

.form-group input {
    width: 100%;
    padding: var(--spacing-sm) var(--spacing-md);
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    color: var(--color-text-primary);
    font-family: var(--font-family);
    font-size: var(--font-size-base);
    transition: all var(--transition-fast);
}

.form-group input:focus {
    border-color: var(--color-accent);
    box-shadow: 0 0 0 3px rgba(212, 175, 55, 0.1);
}

.form-group input::placeholder {
    color: var(--color-text-muted);
}

.error-message {
    display: block;
    color: var(--color-alert);
    font-size: var(--font-size-sm);
    margin-top: var(--spacing-xs);
    min-height: 20px;
}

.newsletter-form .btn {
    min-width: 150px;
    align-self: flex-end;
}

/* ===========================
   Footer
   =========================== */

.footer {
    background-color: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
    margin-top: var(--spacing-2xl);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    padding: var(--spacing-2xl) 0;
    margin-bottom: var(--spacing-lg);
}

.footer-section h3 {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-md);
    color: var(--color-accent);
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-secondary);
    font-size: var(--font-size-sm);
}

.footer-section a:hover {
    color: var(--color-accent);
}

.footer-bottom {
    padding-top: var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    text-align: center;
    color: var(--color-text-muted);
    padding-bottom: var(--spacing-lg);
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 768px) {
    :root {
        --font-size-4xl: 2rem;
        --font-size-3xl: 1.5rem;
        --spacing-2xl: 2rem;
        --spacing-xl: 1.5rem;
    }

    .nav-toggle {
        display: flex;
    }

    .nav-menu {
        display: none;
        position: absolute;
        top: 60px;
        left: 0;
        right: 0;
        flex-direction: column;
        background-color: var(--color-bg-secondary);
        border-bottom: 1px solid var(--color-border);
        gap: 0;
        z-index: 40;
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-menu li {
        padding: var(--spacing-md) var(--spacing-lg);
        border-bottom: 1px solid var(--color-border);
    }

    .nav-link {
        display: block;
        padding: 0;
    }

    .nav-link::after {
        display: none;
    }

    .hero-content h2 {
        font-size: var(--font-size-3xl);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form .btn {
        align-self: stretch;
    }

    .countdown {
        gap: var(--spacing-sm);
    }

    .time-value {
        font-size: var(--font-size-lg);
    }
}

@media (max-width: 480px) {
    :root {
        --font-size-4xl: 1.5rem;
        --font-size-3xl: 1.25rem;
        --spacing-lg: 1rem;
        --spacing-md: 1rem;
    }

    .container {
        padding: 0 var(--spacing-md);
    }

    .header-container {
        padding: var(--spacing-md);
        gap: var(--spacing-md);
    }

    .header-actions {
        gap: var(--spacing-sm);
    }

    .icon-btn {
        width: 36px;
        height: 36px;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
        gap: var(--spacing-md);
    }

    .hero {
        min-height: 300px;
        padding: var(--spacing-lg);
    }

    .section {
        padding: var(--spacing-lg) 0;
    }

    .newsletter-content h2 {
        font-size: var(--font-size-2xl);
    }
}

/* ===========================
   Forced Colors (High Contrast)
   =========================== */

@media (forced-colors: active) {
    .btn-primary {
        border: 2px solid CanvasText;
    }

    .badge {
        background-color: CanvasText;
        color: Canvas;
    }

    .discount-badge {
        background-color: CanvasText;
        color: Canvas;
    }

    .nav-link::after {
        background-color: CanvasText;
    }

    .icon-btn:hover {
        border: 1px solid CanvasText;
    }

    .focus-visible {
        outline: 2px solid CanvasText;
    }
}

/* ===========================
   Reduced Motion
   =========================== */

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* ===========================
   Print Styles
   =========================== */

@media print {
    .header,
    .hero,
    .footer,
    .newsletter-form {
        display: none;
    }

    body {
        background-color: white;
        color: black;
    }

    .product-card {
        page-break-inside: avoid;
    }
}
